   {page==='jobs'&&<section className="panel"><div className="panel-toolbar"><div><ListOrdered size={17}/><strong>Công việc gần đây</strong><span className="badge">{jobs.length}</span></div><div>{batchReady&&<button className="quiet" onClick={()=>void run(saveChapters)}><Download size={15}/>Lưu tất cả chương</button>}<button className="quiet" onClick={()=>void run(refresh)}><RefreshCw size={15}/>Làm mới</button></div></div>{!jobs.length?<Empty icon={ListOrdered} title="Một hàng đợi yên tĩnh">Các tác vụ tạo giọng, chép lời, tải model và xuất audio sẽ xuất hiện ở đây.</Empty>:<div className="jobs-list">{jobs.map(job=><article className="job-row" key={job.id}><span className={`job-icon ${job.status}`}>{job.status==='running'?<LoaderCircle className="spin" size={20}/>:job.status==='succeeded'?<Check size={20}/>:<AudioLines size={20}/>}</span><div className="job-main"><div><strong>{job.kind==='tts'?'Tạo giọng đọc':job.kind==='stt'?'Chép lời':job.kind==='render'?'Xuất audio':job.kind==='clone_preview'?'Làm sạch mẫu giọng':job.kind==='separate'?'Tách nhạc nền':'Tải model'}</strong><span className={`status ${job.status}`}>{statusLabel[job.status]}</span></div><p>{String(job.payload.name??job.payload.text??job.payload.model_id??job.id).slice(0,120)}</p>{job.status==='running'&&<><progress max={1} value={job.progress}/><small className="job-progress">{jobProgressLabel(job.kind,job.progress,job.updated_at)}</small></>} {job.error&&<p className="job-error" title={job.error}>{job.kind==='stt'?jobError(job.error):job.error}</p>}</div><div className="job-actions">{['queued','running'].includes(job.status)&&<button className="quiet" onClick={()=>void run(async()=>{await call('cancel_job',{id:job.id});await refresh();})}>Hủy</button>}{['failed','cancelled','interrupted'].includes(job.status)&&<button className="outlined" onClick={()=>void run(async()=>{await call('retry_job',{id:job.id});await refresh();})}><RefreshCw size={14}/>Thử lại</button>}{job.status==='succeeded'&&job.kind==='stt'&&<button className="outlined" onClick={()=>void run(()=>applyTranscript(job))}>Áp dụng transcript</button>}{job.status==='succeeded'&&job.kind==='tts'&&<button className="outlined" onClick={()=>void run(async()=>{if(job.project_id)await openProject(job.project_id);setPage('tts');})}>Mở take</button>}{job.status==='succeeded'&&job.kind==='render'&&<button className="primary" onClick={()=>void run(async()=>{const path=await pickAudioPath(String(job.payload.format??'wav'),job.payload.name?String(job.payload.name):undefined);if(path)await saveAudio(String(job.result?.asset_id??''),path);})}><Download size={15}/>Lưu audio</button>}</div></article>)}</div>}</section>}
   {page==='projects'&&<><section className="panel project-create"><label className="field">Tên dự án mới<input value={newName} onChange={e=>setNewName(e.target.value)}/></label><button className="primary" disabled={busy} onClick={()=>void run(newProject)}><Plus size={17}/>Tạo dự án</button></section><div className="project-grid">{projects.map(p=><article className="panel project-card" key={p.id}><FolderOpen size={29}/><h3>{p.name}</h3><p>{new Date(p.updated_at).toLocaleString('vi-VN')}</p><div><button className="outlined" onClick={()=>void run(async()=>{await openProject(p.id);setPage('tts');})}>Mở dự án <ChevronRight size={15}/></button><IconButton label={`Xóa dự án ${p.name}`} icon={Trash2} onClick={()=>void run(async()=>{if(!window.confirm(`Xóa dự án “${p.name}”? Media đã tạo vẫn được giữ.`))return;await call('delete_project',{id:p.id});if(project?.id===p.id){setProject(null);projectRef.current=null;resetHistory();setDirty(false);dirtyRef.current=false;}await refresh();})}/></div></article>)}</div>{!projects.length&&<Empty icon={FolderOpen} title="Không gian cho câu chuyện đầu tiên">Tạo dự án để lưu kịch bản, transcript và các phiên bản audio.<br/><button className="outlined empty-demo" disabled={busy} onClick={()=>void run(openDemo)}>Mở dự án mẫu</button></Empty>}</>}
   {page==='models'&&<><div className="model-grid">{models.filter(m=>starters.includes(m.id)).map(modelCard)}</div>{models.length>0&&<details className="mc-more" open={moreOpen} onToggle={e=>setMoreOpen(e.currentTarget.open)}><summary>Thêm model</summary><div className="model-grid">{models.filter(m=>!starters.includes(m.id)).map(modelCard)}</div></details>}{!models.length&&<div className="panel"><Empty icon={Settings2} title="Model local xuất hiện trong bản desktop">Bản xem trước không giả lập trạng thái model đã cài. Trạng thái chỉ được xác nhận từ máy thực.</Empty></div>}<details className="mc-voices" ref={voicesRef} open={voicesOpen} onToggle={ev=>setVoicesOpen(ev.currentTarget.open)}><summary>Thư viện giọng</summary><div className="library-grid"><section><div className="voice-grid">{voices.map(v=><article className="panel voice-card" key={v.id}><div className="voice-avatar"><AudioLines size={25}/></div><span className="eyebrow">{v.kind==='preset'?'PRESET':'GIỌNG THAM CHIẾU'}</span><h3>{v.name}</h3><p>{v.kind==='reference'?'Mẫu cá nhân · Lưu tại máy':'Giọng có sẵn của engine'}</p><span className="badge">{v.kind==='reference'?'Đã xác nhận quyền sử dụng':'Local engine'}</span></article>)}</div>{!voices.length&&<div className="panel"><Empty icon={Mic2} title="Thư viện giọng của riêng bạn">Tải model để dùng preset hoặc thêm một mẫu giọng có quyền sử dụng.</Empty></div>}</section><section className="panel voice-form"><div className="inspector-heading"><Plus size={18}/><h3>Thêm mẫu giọng</h3></div><label className="field">Tên hiển thị<input placeholder="Ví dụ: Giọng kể của tôi" value={voiceName} onChange={e=>setVoiceName(e.target.value)}/></label><button className="outlined full" disabled={!desktop} onClick={()=>void run(async()=>{const paths=await pickFiles('audio');if(paths[0])setVoiceRef(await call<Asset>('import_asset',{path:paths[0]}));})}><Upload size={16}/>{voiceRef?.name??'Chọn mẫu audio'}</button><p className="hint">Mẫu giọng rõ, một người nói, hạn chế nhạc nền và tiếng ồn. Giữ nguyên file gốc.</p><ReasonButton className="outlined full" blocked={voiceReady?null:'Tải VieNeu v3 Turbo trong Model & cài đặt để bật'} disabled={busy||!desktop||!voiceRef||!!cleanJob} onClick={()=>void run(previewSample)}><Headphones size={16}/>{cleanJob?.status==='queued'?'Đang chờ hàng đợi…':cleanJob?'Đang làm sạch…':'Nghe mẫu đã làm sạch'}</ReasonButton><p className="hint">Chỉ dùng 8 giây có âm thanh to và liền mạch nhất của mẫu (nhạc hoặc tiếng ồn to cũng có thể được chọn), đã lọc ồn. Nghe thử: nếu còn nhạc, tiếng ồn hoặc giọng khác, hãy chọn mẫu khác.</p><audio ref={cleanPlayer} aria-label="Mẫu đã làm sạch" hidden/><label className="check consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Tôi có quyền sử dụng và tạo giọng từ mẫu audio này.</span></label><button className="primary full" disabled={busy||!desktop||!voiceRef||!consent||!voiceName.trim()} onClick={()=>void run(registerVoice)}>Lưu mẫu giọng</button></section></div></details><details className="mc-advanced" open={advOpen} onToggle={e=>setAdvOpen(e.currentTarget.open)}><summary>Nâng cao</summary><div className="runtime-panel panel"><div><ShieldCheck size={25}/><h3>Chạy local. Chủ động dữ liệu.</h3><p>{runtime?.message??'Đang kiểm tra runtime…'}</p></div><div className="runtime-checks">{[['Python',runtime?.python_ready],['Bộ xử lý',runtime?.worker_ready],['FFmpeg',runtime?.ffmpeg_ready]].map(([name,ready])=><span key={String(name)} className={ready?'is-ready':''}>{ready?<Check size={16}/>:<span className="small-dot"/>}{name} · {ready?'Sẵn sàng':'Chưa sẵn sàng'}</span>)}</div></div><section className="panel engine-panel"><div><h3>Bộ xử lý</h3><p>Thao tác chạy bằng bộ xử lý gốc khi bản này có, và tự chạy lại bằng Python nếu bộ xử lý gốc gặp lỗi nội bộ. Bộ xử lý gốc · {runtime?.native_worker_ready?'Sẵn sàng':'Chưa có trong bản này'} · Đã chạy lại bằng Python: {runtime?.fallback_count??0} lần.</p></div><div className="engine-rows">{([['tts','Đọc văn bản'],['stt','Chép lời'],['render','Xuất âm thanh'],['download','Tải model'],['clone_preview','Nghe thử giọng nhân bản']] as const).map(([op,label])=><label key={op}><span>{label}</span><select value={engines[op]??'auto'} disabled={!desktop||busy} onChange={e=>void run(()=>saveEngine(op,e.target.value as WorkerEngine))}><option value="auto">Tự động</option><option value="python">Luôn dùng Python</option></select></label>)}</div></section><button className="outlined mc-diag" disabled={busy} onClick={()=>void run(saveDiagnostics)}><Download size={16}/>Xuất nhật ký chẩn đoán</button></details><section className="panel app-dictionary"><div className="inspector-heading"><BookOpen size={17}/><h3>Từ điển phát âm chung</h3></div><DictionaryEditor entries={appDictionary} hint="Áp dụng cho mọi dự án. Từ điển của từng dự án thắng khi trùng từ gốc." onAdd={(k,v)=>void run(()=>saveAppDictionary({...appDictionary,[k]:v}))} onRemove={k=>void run(()=>{const d={...appDictionary};delete d[k];return saveAppDictionary(d);})} onImport={()=>void run(()=>importDictionary('app'))} onExport={()=>void run(()=>saveText('Từ điển chung.csv',dictionaryToCsv(appDictionary)))}/></section><UpdateSettings current={version} auto={updates.auto} state={updates.state} onAuto={updates.setAuto} onCheck={()=>void updates.check(true).then(v=>setNotice(v?`Bản ${v} đã tải xong. App sẽ cài khi bạn đóng cửa sổ.`:`Bạn đang dùng bản mới nhất (${version}).`)).catch(()=>{})} onShowChanges={()=>setChanges(CHANGELOG)}/><div className="settings-note"><Volume2 size={18}/><p>CPU là cấu hình mặc định. GPU chỉ bật sau kiểm chứng tương thích. Không tự tải model hay gửi nội dung ra ngoài; app chỉ hỏi GitHub để tìm bản mới (tắt được ở mục Cập nhật).</p></div></>}
